import { h } from 'preact';
import { ButtonProps } from './Button.types';
import styles from './Button.module.scss';

export const Button = ({
  variant = 'primary',
  size = 'medium',
  disabled = false,
  children,
  onClick,
  ...props
}: ButtonProps) => {
  const classNames = [
    styles.button,
    styles[`button--${variant}`],
    styles[`button--${size}`],
    disabled && styles['button--disabled']
  ].filter(Boolean).join(' ');

  return (
    <button
      className={classNames}
      disabled={disabled}
      onClick={onClick}
      aria-label={props['aria-label']}
      {...props}
    >
      {children}
    </button>
  );
};

