    'font-weight-normal': 400,
    'font-weight-medium': 500,
    'font-weight-bold': 700,
    'line-height-base': 1.5
  ),
  'spacing': (
    'xs': 4px,
    'sm': 8px,
    'md': 16px,
    'lg': 24px,
    'xl': 32px,
    'xxl': 48px
  ),
  'border-radius': (
    'sm': 4px,
    'md': 8px,
    'lg': 12px,
    'full': 9999px
  )
);

@function theme-get($keys...) {
  $value: $theme-default;
  @each $key in $keys {
    $value: map.get($value, $key);
  }
  @return $value;
}

